-- ── story 2-6a: serial / IMEI capture at receipt ─────────────────────────
-- Generated by drizzle-kit (the column, the table and its three indexes) and
-- hand-amended around the generated part: the fail-fast guard, `IF NOT
-- EXISTS` on the table and its indexes (guide §3, linted from 0089 on), the
-- CHECKs, the RLS policy and the post-migration probe (drizzle-kit is blind to
-- CHECKs and RLS; `bun run db:generate` afterwards reports "No schema
-- changes").
--
-- 1. `skus.serial_format text NOT NULL DEFAULT 'free'` — `free` | `imei`
--    (`SERIAL_FORMATS`, src/shared/primitives/serial.ts). A constant default,
--    so the ADD COLUMN is metadata-only (no rewrite). Its CHECK is added NOT
--    VALID and NOT validated here (the 4-2a / 0093 rule, guide §3): every
--    existing row reads the constant default, which the CHECK admits by
--    construction, and the migrator runs the whole pending set in ONE
--    transaction, so a VALIDATE beside the ADD would scan `skus` under the ADD
--    COLUMN's ACCESS EXCLUSIVE lock. The VALIDATE is bookkeeping for a later
--    deploy (PENDING). NOT VALID still enforces every insert and update.
-- 2. `goods_receipt_line_serials` — one row per captured unit of a GRN line,
--    in capture order (`ordinal`). New and empty, so its indexes are built
--    here. `goods_receipt_lines` is NOT altered. No FKs (guide §3).
--
-- Lock cost: the ADD COLUMN takes a brief ACCESS EXCLUSIVE lock on `skus` (no
-- rewrite, no scan). The deploy migrator sets `lock_timeout` on every
-- connection (MIGRATE_LOCK_TIMEOUT_MS, default 5 s): if the lock cannot be
-- taken the deploy fails cleanly, the pending set rolls back whole, and it is
-- re-run (DEPLOY.md §5).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'skus' AND column_name = 'serial_format'
	) THEN
		RAISE EXCEPTION 'migration 0096: skus.serial_format already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "goods_receipt_line_serials" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"grn_id" uuid NOT NULL,
	"grn_line_id" uuid NOT NULL,
	"ordinal" integer NOT NULL,
	"serial_id" uuid,
	"state" text NOT NULL,
	"over_receipt_id" uuid,
	"after_write_off" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	-- ── hand-amended: the CHECKs (migration SQL only) ───────────────────
	-- `state` is NOT NULL, so no arm needs `IS NOT NULL` before `IN`; the
	-- nullable `serial_id` and `over_receipt_id` are paired explicitly.
	-- Mirrored by GRN_LINE_SERIAL_STATES / MAX_GRN_SERIALS_PER_LINE
	-- (src/shared/primitives/serial.ts), pinned by test/serial-receipt.spec.ts.
	CONSTRAINT "grls_state_check" CHECK ("state" IN ('applied','pending','rejected','unreadable')),
	CONSTRAINT "grls_ordinal_range" CHECK ("ordinal" BETWEEN 0 AND 499),
	CONSTRAINT "grls_serial_pairing" CHECK (("state" = 'unreadable') = ("serial_id" IS NULL)),
	-- An `applied` row may keep the over-receipt it was approved from; a
	-- `pending` / `rejected` row names one; an `unreadable` row never does.
	-- Written as an equivalence (not one arm per state) so a state outside
	-- the vocabulary is refused by `grls_state_check`, by name, not here.
	CONSTRAINT "grls_over_receipt_pairing" CHECK (
		"state" = 'applied' OR (("state" IN ('pending','rejected')) = ("over_receipt_id" IS NOT NULL))),
	CONSTRAINT "grls_write_off_pairing" CHECK (NOT "after_write_off" OR "serial_id" IS NOT NULL)
);
--> statement-breakpoint
ALTER TABLE "skus" ADD COLUMN "serial_format" text DEFAULT 'free' NOT NULL;--> statement-breakpoint
-- ── hand-amended: the serial-format CHECK, NOT VALID (see the header) ────
ALTER TABLE "skus" ADD CONSTRAINT "skus_serial_format_check" CHECK ("serial_format" IN ('free','imei')) NOT VALID;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "goods_receipt_line_serials_line_ordinal_unique" ON "goods_receipt_line_serials" USING btree ("tenant_id","grn_line_id","ordinal");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "goods_receipt_line_serials_tenant_serial_idx" ON "goods_receipt_line_serials" USING btree ("tenant_id","serial_id") WHERE "serial_id" IS NOT NULL;--> statement-breakpoint
-- The pending backstop (A5): a serial is on at most one open over-receipt,
-- tenant-wide. The submit refuses `serial-pending-approval` first; this is
-- what makes a race between two receipts a unique violation, never two
-- pending rows.
CREATE UNIQUE INDEX IF NOT EXISTS "goods_receipt_line_serials_pending_unique" ON "goods_receipt_line_serials" USING btree ("tenant_id","serial_id") WHERE "state" = 'pending';--> statement-breakpoint
-- ── hand-amended: RLS (migration SQL only; the 0086 shape) ───────────────
ALTER TABLE "goods_receipt_line_serials" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "goods_receipt_line_serials_tenant_isolation" ON "goods_receipt_line_serials"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0087 / 0093 model) ─────────────────
-- Made-up uuids. (a) The serial-format CHECK is present and NOT VALID, and a
-- SKU inserted without a format reads back 'free'. (b) The accepted shapes
-- are inserted and rolled back by a sentinel exception, so a CHECK that
-- refused everything fails the migration. (c) Each refused shape runs in its
-- own subtransaction and must be refused BY ITS NAMED CONSTRAINT; each
-- satisfies every other constraint.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	g uuid := gen_random_uuid();
	l uuid := gen_random_uuid();
	o uuid := gen_random_uuid();
	s1 uuid := gen_random_uuid();
	k uuid;
	read_format text;
	refused_by text;
	expected text;
	probe text;
	unvalidated int;
BEGIN
	SELECT count(*) INTO unvalidated
	  FROM pg_constraint
	 WHERE conrelid = 'public.skus'::regclass
	   AND conname = 'skus_serial_format_check'
	   AND contype = 'c'
	   AND NOT convalidated;
	IF unvalidated <> 1 THEN
		RAISE EXCEPTION 'migration 0096: expected skus_serial_format_check present and NOT VALID, found % so.', unvalidated;
	END IF;
	-- (a) + (b) the default and the accepted shapes.
	BEGIN
		k := gen_random_uuid();
		INSERT INTO "skus" ("id","tenant_id","client_id","code","name","uom","gst_rate_bps","barcode","serial_tracked")
		VALUES (k, t, c, 'P0096-A', 'probe', 'each', 1800, 'P0096-A', true);
		SELECT "serial_format" INTO read_format FROM "skus" WHERE "id" = k;
		IF read_format IS DISTINCT FROM 'free' THEN
			RAISE EXCEPTION 'migration 0096: a SKU inserted without a serial format read back % (expected free).', coalesce(read_format, 'NULL');
		END IF;
		INSERT INTO "skus" ("id","tenant_id","client_id","code","name","uom","gst_rate_bps","barcode","serial_tracked","serial_format")
		VALUES (gen_random_uuid(), t, c, 'P0096-B', 'probe', 'each', 1800, 'P0096-B', true, 'imei');
		INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state","over_receipt_id","after_write_off")
		VALUES
			(gen_random_uuid(), t, g, l, 0, gen_random_uuid(), 'applied', NULL, false),
			(gen_random_uuid(), t, g, l, 1, gen_random_uuid(), 'applied', o, false),
			(gen_random_uuid(), t, g, l, 2, s1, 'pending', o, false),
			(gen_random_uuid(), t, g, l, 3, s1, 'rejected', o, false),
			(gen_random_uuid(), t, g, l, 4, NULL, 'unreadable', NULL, false),
			(gen_random_uuid(), t, g, l, 5, gen_random_uuid(), 'applied', NULL, true),
			(gen_random_uuid(), t, g, l, 499, gen_random_uuid(), 'applied', NULL, false);
		RAISE EXCEPTION USING ERRCODE = 'P0096', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0096: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0096' THEN
			NULL;
	END;
	-- (c) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'format IMEI', 'state booked', 'ordinal 500', 'ordinal -1', 'unreadable with serial', 'applied without serial',
		'pending without over-receipt', 'rejected without over-receipt', 'unreadable with over-receipt',
		'write-off on unreadable', 'second pending', 'duplicate ordinal'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'format IMEI' THEN 'skus_serial_format_check'
			WHEN 'state booked' THEN 'grls_state_check'
			WHEN 'ordinal 500' THEN 'grls_ordinal_range'
			WHEN 'ordinal -1' THEN 'grls_ordinal_range'
			WHEN 'unreadable with serial' THEN 'grls_serial_pairing'
			WHEN 'applied without serial' THEN 'grls_serial_pairing'
			WHEN 'pending without over-receipt' THEN 'grls_over_receipt_pairing'
			WHEN 'rejected without over-receipt' THEN 'grls_over_receipt_pairing'
			WHEN 'unreadable with over-receipt' THEN 'grls_over_receipt_pairing'
			WHEN 'write-off on unreadable' THEN 'grls_write_off_pairing'
			WHEN 'duplicate ordinal' THEN 'goods_receipt_line_serials_line_ordinal_unique'
			ELSE 'goods_receipt_line_serials_pending_unique'
		END;
		BEGIN
			CASE probe
				WHEN 'format IMEI' THEN
					INSERT INTO "skus" ("id","tenant_id","client_id","code","name","uom","gst_rate_bps","barcode","serial_tracked","serial_format")
					VALUES (gen_random_uuid(), t, c, 'P0096-C', 'probe', 'each', 1800, 'P0096-C', true, 'IMEI');
				WHEN 'state booked' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state")
					VALUES (gen_random_uuid(), t, g, l, 0, gen_random_uuid(), 'booked');
				WHEN 'ordinal 500' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state")
					VALUES (gen_random_uuid(), t, g, l, 500, gen_random_uuid(), 'applied');
				WHEN 'ordinal -1' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state")
					VALUES (gen_random_uuid(), t, g, l, -1, gen_random_uuid(), 'applied');
				WHEN 'unreadable with serial' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state")
					VALUES (gen_random_uuid(), t, g, l, 0, gen_random_uuid(), 'unreadable');
				WHEN 'applied without serial' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state")
					VALUES (gen_random_uuid(), t, g, l, 0, NULL, 'applied');
				WHEN 'pending without over-receipt' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state")
					VALUES (gen_random_uuid(), t, g, l, 0, gen_random_uuid(), 'pending');
				WHEN 'rejected without over-receipt' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state")
					VALUES (gen_random_uuid(), t, g, l, 0, gen_random_uuid(), 'rejected');
				WHEN 'unreadable with over-receipt' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state","over_receipt_id")
					VALUES (gen_random_uuid(), t, g, l, 0, NULL, 'unreadable', o);
				WHEN 'write-off on unreadable' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state","after_write_off")
					VALUES (gen_random_uuid(), t, g, l, 0, NULL, 'unreadable', true);
				WHEN 'second pending' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state","over_receipt_id")
					VALUES (gen_random_uuid(), t, g, l, 0, s1, 'pending', o), (gen_random_uuid(), t, g, gen_random_uuid(), 0, s1, 'pending', o);
				WHEN 'duplicate ordinal' THEN
					INSERT INTO "goods_receipt_line_serials" ("id","tenant_id","grn_id","grn_line_id","ordinal","serial_id","state")
					VALUES (gen_random_uuid(), t, g, l, 7, gen_random_uuid(), 'applied'), (gen_random_uuid(), t, g, l, 7, gen_random_uuid(), 'applied');
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0096: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "goods_receipt_line_serials" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "skus" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0096: a probe row survived.';
	END IF;
END $$;
